Form.Script:
include "common/Common.js";

// ---------- 직접 호출: 고객 검색 ----------
function btn_search_OnClick(obj)
{
    ds_search.ClearData();
    ds_search.AddRow();
    ds_search.SetColumn(0, "keyword", edt_keyword.Text);

    Transaction("svcCustomerSearch",
                "http://localhost:8080/bank/miplatform/customer/search",
                "ds_search=ds_search",
                "ds_customer=ds_customer",
                "",
                "fn_callback");
}

// ---------- 공통 래퍼 호출: 고객 등록 ----------
function btn_register_OnClick(obj)
{
    ds_new.ClearData();
    ds_new.AddRow();
    ds_new.SetColumn(0, "custNm", edt_nm.Text);
    ds_new.SetColumn(0, "phone", edt_phone.Text);
    ds_new.SetColumn(0, "email", edt_email.Text);

    // 서버의 ds_customer(입력용) <- 클라이언트 ds_new
    gfn_transaction("svcCustomerRegister",
                    "/miplatform/customer/register",
                    "ds_customer=ds_new",
                    "",
                    "",
                    "fn_callback");
}

function fn_callback(strSvcId, nErrorCode, strErrorMsg)
{
    if (gfn_isError(nErrorCode, strErrorMsg)) {
        return;
    }
    if (strSvcId == "svcCustomerRegister") {
        alert("고객이 등록되었습니다. 고객번호: " + custNo);   // 서버가 내려준 변수 custNo
        btn_search_OnClick(btn_search);
    }
}
